export default class Progress {
  execute(cellConfig, caseObj, result) {
    if (result === false) {
      this.toOrg(cellConfig, caseObj);
      return;
    }
    let progress = caseObj.touchOff.progress;
    let { top, right, bottom, left } = progress.config;
    if (!top && !right && !bottom && !left) {
      return;
    }
    let value = `${(1 - result) * 100}%`;
    let inset = `inset(${top ? value : '0%'} ${right ? value : '0%'} ${
      bottom ? value : '0%'
    } ${left ? value : '0%'})`;
    progress.selector.forEach((selectObj) => {
      cellConfig.cell.attr(selectObj + '/clipPath', inset);
    });
  }
  toOrg(cellConfig, caseObj) {
    let progress = caseObj.touchOff.progress;
    if (progress?.selector?.length) {
      progress.selector.forEach((selectObj) => {
        cellConfig.cell.attr(selectObj + '/clipPath', 'unset');
      });
    }
  }
}
