import { NODE_NEME } from '../constants/Constants';
import {
  DEFAULT_ANGLE_MULTIPLE,
  snapPointByAngleMultiple
} from '../util/EdgeSnapUtil';
class DrawEdge {
  constructor() {
    this.angleMultiple = DEFAULT_ANGLE_MULTIPLE;
    this.startDrawListening = [];
    this.endDrawListening = [];
    this.clickTimestamp = 0;
    this.startListening = this.startListening.bind(this);
    this.stopListening = this.stopListening.bind(this);
    this.handleClick = this.handleClick.bind(this);
    this.setTarget = this.setTarget.bind(this);
  }
  start(graph, shape) {
    this.shape = shape;
    this.stopListening();
    this.graph = graph;
    this.graph.cleanSelection();
    this.graph.clearTransformWidgets();
    this.startListening();
    this.startDrawListening.forEach((callback) => {
      callback();
    });
  }
  stop() {
    this.stopListening();
    this.endDrawListening.forEach((callback) => {
      callback();
    });
  }
  startListening() {
    this.graph.container.addEventListener('click', this.handleClick);
    // this.graph.container.addEventListener('dbclick', this.endDraw);
    this.graph.container.addEventListener('mousemove', this.setTarget);
  }
  stopListening() {
    if (this.drawEdge) {
      this.drawEdge = null;
    }
    if (this.graph) {
      this.graph.container.removeEventListener('click', this.handleClick);
      this.graph.container.removeEventListener('mousemove', this.setTarget);
      this.graph = null;
    }
  }
  handleClick(e) {
    const currentTimestamp = new Date().getTime();
    let isOrgPoint = true;
    if (this.preEvent) {
      let { pageX: x1, pageY: y1 } = this.preEvent;
      let { pageX: x2, pageY: y2 } = e;
      const distance = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
      isOrgPoint = distance < 5;
    }
    this.preEvent = e;
    if (currentTimestamp - this.clickTimestamp < 300 && isOrgPoint) {
      let vertices = this.drawEdge.getVertices();
      vertices.pop();
      this.drawEdge.setVertices(vertices);
      // this.drawEdge.prop('lock', false);
      this.stop();
    } else {
      this.draw(e);
    }

    this.clickTimestamp = currentTimestamp;
  }
  draw(e) {
    let { pageX, pageY } = e;
    let p = this.graph.pageToLocal(pageX, pageY);
    if (!this.drawEdge) {
      // this.graph.startBatch('draw');
      this.startDraw(p);
    } else {
      this.addVertices();
      this.isMove = false;
      this.graph.stopBatch('draw');
    }
  }
  /* 开始画 */
  startDraw({ x, y }) {
    let { shape, name } = this.shape;
    this.drawEdge = this.graph.addEdge({
      [NODE_NEME]: `${name}_${this.graph.getCellCount() + 1}`,
      shape: shape,
      source: { x: x, y: y },
      target: { x: x, y: y },
      vertices: [],
      // lock: true,
      connector: {
        name: '' //'jumpover'
      }
    });
  }
  /* 添加锚点 */
  addVertices() {
    let vertices = this.drawEdge.getVertices();
    let p = this.drawEdge.getTarget();
    vertices.push(p);
    this.drawEdge.setVertices(vertices);
  }
  setTarget(e) {
    if (this.drawEdge) {
      if (!this.isMove) {
        this.graph.startBatch('draw');
      }
      this.isMove = true;
      if (e.shiftKey) {
        let vertices = this.drawEdge.getVertices();
        let firstPoint;
        if (vertices && vertices.length > 0) {
          firstPoint = {
            x: vertices[vertices.length - 1].x,
            y: vertices[vertices.length - 1].y
          };
        } else {
          firstPoint = this.drawEdge.getSource();
        }
        let { pageX, pageY } = e;
        let p = this.graph.pageToLocal(pageX, pageY);
        const secondPoint = snapPointByAngleMultiple(
          { x: p.x, y: p.y },
          firstPoint,
          this.angleMultiple
        );
        this.drawEdge.setTarget(secondPoint);
      } else {
        let { pageX, pageY } = e;
        let p = this.graph.pageToLocal(pageX, pageY);
        this.drawEdge.setTarget(p);
      }
    }
  }
  /* 监听开始绘制 */
  onStartDrawListening(callback = () => {}) {
    let findHook = this.startDrawListening.find(
      (localHook) =>
        localHook === callback && localHook.toString() === callback.toString()
    );
    if (!findHook) {
      this.startDrawListening.push(callback);
    }
  }
  /* 监听结束绘制 */
  onEndDrawListening(callback = () => {}) {
    this.endDrawListening.push(callback);
    let findHook = this.endDrawListening.find(
      (localHook) =>
        localHook === callback && localHook.toString() === callback.toString()
    );
    if (!findHook) {
      this.endDrawListening.push(callback);
    }
  }
}
export default new DrawEdge();
