<template>
  <div id="app">
    <Webtopo
      :webtopoAPI="webAPI"
      v-if="key === null"
      :isLocal="false"
      :consId="consId"
      :svgId="svgId"
      :modelTemplateDefaultOpen="true"
      :showModelTemplateButton="true"
      @saved="onBlueprintSaved"
    ></Webtopo>
    <preview
      v-else
      :svgId="`${key}.json`"
      :webtopoAPI="webAPI"
      :isConnect="isConnect"
      ref="preview"
      @register="register"
      :isPreview="true"
      :isLocal="false"
    ></preview>
    <div class="demo-tools" v-if="key !== null">
      <div class="demo-tools__title">预览接入示例</div>
      <div class="demo-tools__row">
        <button @click="pushOneData">推送单点数据</button>
        <button @click="pushBatchData">推送批量数据</button>
        <button @click="toggleFullscreen">全屏/退出</button>
        <button v-if="!autoPush" @click="startMockPush">开启自动推送</button>
        <button v-else @click="stopMockPush">停止自动推送</button>
      </div>
      <div class="demo-tools__status">
        连接状态：{{ isConnect ? '已连接' : '未连接' }}， 注册点位数：{{
          registeredPoints.length
        }}， 最近推送：{{ lastPushAt || '--' }}
      </div>
    </div>
  </div>
</template>

<script>
  import * as webAPI from './api/index.js';
  export default {
    name: 'App',
    data() {
      return {
        webAPI,
        key: null,
        isConnect: false,
        consId: '', // 可从登录态、路由、租户上下文中获取
        registeredPoints: [], // preview 通过 register 事件回传的点位清单
        autoPush: false,
        mockTimerId: null,
        lastPushAt: '',
        svgId: '',
        realDataTimerId: null
      };
    },
    created() {
      const urlParams = new URLSearchParams(window.location.search);
      const key = urlParams.get('key');
      this.key = key;
      // 示例：从 URL 获取租户/客户 id
      this.consId = urlParams.get('consId') || '';
      this.svgId = urlParams.get('id') || '';
    },
    methods: {
      onBlueprintSaved(payload) {
        console.log('[demo] blueprint saved:', payload);
      },
      /**
       * 图纸加载完成时触发：
       * 1) 可把点位信息发给你的实时服务做订阅（socket / mqtt / http 轮询）
       * 2) 后续拿到数据后调用 this.$refs.preview.changeData(data)
       */
      register(pointList) {
        this.registeredPoints = Array.isArray(pointList) ? pointList : [];
        this.isConnect = true;
        console.log('[demo] register points:', this.registeredPoints);
        if (this.registeredPoints.length) {
          this.startRealDataTimer();
        } else {
          this.stopRealDataTimer();
        }
      },
      startMockPush() {
        if (this.mockTimerId) return;
        this.autoPush = true;
        // 示例：每 3 秒模拟一次实时数据推送
        this.mockTimerId = setInterval(() => {
          this.pushOneData();
        }, 3000);
      },
      stopMockPush() {
        this.autoPush = false;
        if (this.mockTimerId) {
          clearInterval(this.mockTimerId);
          this.mockTimerId = null;
        }
      },
      pushOneData() {
        const point = this.pickOneAttr();
        if (!point) {
          console.warn(
            '[demo] 未获取到可推送的点位，请先打开图纸并等待 register 回调'
          );
          return;
        }
        this.$refs.preview.changeData(this.buildData(point));
        this.lastPushAt = new Date().toLocaleTimeString();
      },
      pushBatchData() {
        if (!this.registeredPoints.length) {
          console.warn('[demo] 点位列表为空，无法批量推送');
          return;
        }
        const list = [];
        // 示例批量推送 3 条，可按业务改为后端实际返回条数
        for (let i = 0; i < 3; i += 1) {
          const point = this.pickOneAttr();
          if (point) {
            list.push(this.buildData(point));
          }
        }
        if (!list.length) return;
        this.$refs.preview.changeData(list);
        this.lastPushAt = new Date().toLocaleTimeString();
      },
      buildData(point) {
        return {
          mpId: String(point.mpId),
          attrId: String(point.attrId),
          value: Number((Math.random() * 100).toFixed(2)),
          // 组件内部按秒级时间戳处理
          dataTime: Math.floor(Date.now() / 1000)
        };
      },
      /**
       * 兼容 pointList 中 attrs 既可能是数组，也可能是对象映射。
       */
      pickOneAttr() {
        // if (!this.registeredPoints.length) return null;
        // return this.registeredPoints[Math.floor(Math.random() * this.registeredPoints.length)];

        return { mpId: 2, attrId: 1 };
      },
      async fetchRealData() {
        if (!this.registeredPoints || this.registeredPoints.length === 0) {
          return;
        }
        try {
          const payload = {
            mps: this.registeredPoints
          };
          const result = await this.webAPI.getRealData(payload);
          this.$refs.preview.changeData(result);
          console.log('实时数据', result);
        } catch (error) {
          console.error('getRealData 获取实时数据失败', error);
        }
      },
      startRealDataTimer() {
        // this.stopRealDataTimer();
        // this.fetchRealData();
        // this.realDataTimerId = setInterval(() => {
        //   console.log('开始获取实时数据');
        //   this.fetchRealData();
        // }, 10000);
      },
      stopRealDataTimer() {
        if (this.realDataTimerId) {
          // clearInterval(this.realDataTimerId);
          this.realDataTimerId = null;
        }
      },
      toggleFullscreen() {
        if (
          this.$refs.preview &&
          this.$refs.preview.toggleFullscreen
        ) {
          this.$refs.preview.toggleFullscreen();
        }
      }
    },
    beforeDestroy() {
      this.stopMockPush();
      this.stopRealDataTimer();
    }
  };
</script>

