import { SUPER_G_NAME } from '../../constants/Constants';
export default class Status {
  execute(cellConfig, caseObj, result) {
    if (result === true) {
      this.toEffect(cellConfig, caseObj);
    } else {
      this.toOrg(cellConfig, caseObj);
    }
  }
  //变化到指定样式
  toEffect(cellConfig, caseObj) {
    if (typeof caseObj.touchOff.status == 'object') {
      for (let [, value] of Object.entries(caseObj.touchOff.status)) {
        //如果状态为修改样式
        if (value?.statu?.style) {
          cellConfig.cell.attr(value?.statu?.style);
        }
        if (value?.statu?.class) {
          let selector = value?.statu?.class?.selector;
          let className = value?.statu?.class?.className;
          if (!selector || selector == '') {
            selector = SUPER_G_NAME;
          }
          let classs = cellConfig.cell.attr(`${selector}/class`);
          if (classs) {
            className += ' ' + classs;
          }
          cellConfig.cell.attr(`${selector}/class`, className);
        }
      }
    }
    // cellConfig.cell.attr(caseObj.touchOff.style);
  }
  //恢复到最初样式
  toOrg(cellConfig, caseObj) {
    // cellConfig.cell.removeAttrByPath('water/visibility');
    // cellConfig.cell.removeAttrs({ silent: false });
    for (let [, value] of Object.entries(caseObj.touchOff.status)) {
      //如果状态为修改样式
      if (value?.statu?.style) {
        // cellConfig.orgCell.attrs, { silent: true }
        /* cellConfig.cell.removeAttrByPath('fill');
        cellConfig.cell.removeAttrByPath('stroke');
        cellConfig.cell.setAttrByPath('fill', cellConfig.orgCell.attrs.fill);
        cellConfig.cell.setAttrByPath(
          'stroke',
          cellConfig.orgCell.attrs.stroke
        ); */
        // { dirty: true }

        let statuStyle = value?.statu?.style;
        this.recursionRemoveAttr([], statuStyle, cellConfig.cell);
        cellConfig.cell.attr(cellConfig.orgCell.attrs);
        // cellConfig.cell.remove();
        // cellConfig.orgCell;
      }
      if (value?.statu?.class) {
        let selector = value?.statu?.class?.selector;
        let className = value?.statu?.class?.className;
        if (!selector || selector == '') {
          selector = SUPER_G_NAME;
        }
        let classs = cellConfig.cell.attr(`${selector}/class`);
        if (classs != undefined) {
          classs = classs.replaceAll(className, '');
          cellConfig.cell.attr(`${selector}/class`, classs);
        }
      }
    }
  }
  recursionRemoveAttr(path, attr, cell) {
    Object.entries(attr).forEach(([key, value]) => {
      // cell.attr(key + '/style' + '/animation', 'none');
      // 最后一个非对象属性执行这里
      path.push(key);
      if (typeof value !== 'object') {
        cell.attr(path.join('/'), 'none', { silent: true });
      } else {
        this.recursionRemoveAttr(path, value, cell);
      }
    });
  }
}
