import { Timing } from '@antv/x6';
import { SUPER_G_NAME } from '../../constants/Constants';

export default class GDAnimation {
  execute(cellConfig, caseObj, result, isEditView) {
    if (result === true) {
      this.start(cellConfig, caseObj);
    } else {
      this.stop(cellConfig, caseObj);
    }
  }
  start(cellConfig, caseObj) {
    let {
      attr,
      orgValue,
      targetValue,
      duration, //执行时长
      delay,
      timing = 'quad'
    } = caseObj.touchOff.gdanimation;
    cellConfig.cell.stopTransition(`attrs/${SUPER_G_NAME}/${attr}`);
    cellConfig.cell.attr(`${SUPER_G_NAME}/${attr}`, orgValue);
    cellConfig.cell.transition(`attrs/${SUPER_G_NAME}/${attr}`, targetValue, {
      delay: delay, //延时执行
      duration: duration,
      timing: Timing.decorators.reverse(Timing[timing]),
      finish: () => {
        console.log('执行了');
      }
    });
  }
  stop(cellConfig, caseObj) {
    let {
      attr,
      orgValue,
      targetValue,
      duration, //执行时长
      delay,
      timing = 'quad'
    } = caseObj.touchOff.gdanimation;
    cellConfig.cell.stopTransition(`attrs/${SUPER_G_NAME}/${attr}`);
    cellConfig.cell.attr(`${SUPER_G_NAME}/${attr}`, targetValue);
    cellConfig.cell.transition(`attrs/${SUPER_G_NAME}/${attr}`, orgValue, {
      delay: delay, //延时执行
      duration: duration,
      timing: Timing.decorators.reverse(Timing[timing]),
      finish: () => {
        console.log('执行了');
      }
    });
  }
}
