import { isFreeEdge, partitionAlignCells } from '../util/CellSelectionUtil';
import { translateFreeEdge } from '../util/EdgeAlignUtil';

let disposeFn = null;

function isMultiSelectModifier(e) {
  return !!(e?.ctrlKey || e?.metaKey || e?.shiftKey || e?.altKey);
}

function isEdgeToolTarget(e) {
  const target = e?.target;
  if (!target?.closest) {
    return false;
  }
  return !!target.closest('.x6-edge-tool');
}

function isMovableCell(cell) {
  if (!cell) {
    return false;
  }
  if (cell.prop('lock') || cell.prop('group-lock')) {
    return false;
  }
  if (cell.isEdge?.()) {
    return isFreeEdge(cell);
  }
  return true;
}

function getGroupDragSelection(graph) {
  const selected = graph.getSelectedCells().filter(isMovableCell);
  const { nodes, edges } = partitionAlignCells(selected);
  return { selected, nodes, edges };
}

function shouldGroupDragFromEdge(graph, edge) {
  if (!edge?.isEdge?.() || !isFreeEdge(edge) || !graph.isSelected(edge)) {
    return false;
  }
  const { selected, nodes, edges } = getGroupDragSelection(graph);
  if (edges.length >= 2) {
    return true;
  }
  return edges.length >= 1 && nodes.length >= 1 && selected.length > 1;
}

function shouldDisableNativeEdgeDrag(graph, cell) {
  if (!cell?.isEdge?.() || !isFreeEdge(cell) || !graph.isSelected(cell)) {
    return false;
  }
  const { selected, nodes, edges } = getGroupDragSelection(graph);
  if (edges.length >= 2) {
    return true;
  }
  return edges.length >= 1 && nodes.length >= 1 && selected.length > 1;
}

function resolveInteractingResult(result) {
  if (result === false) {
    return false;
  }
  if (result === true || result == null) {
    return {};
  }
  return { ...result };
}

function wrapInteracting(graph, originInteracting) {
  return (view) => {
    const cell = view?.cell;
    let result =
      typeof originInteracting === 'function'
        ? originInteracting(view)
        : originInteracting;
    if (!shouldDisableNativeEdgeDrag(graph, cell)) {
      return result;
    }
    if (result === false) {
      return false;
    }
    return {
      ...resolveInteractingResult(result),
      edgeMovable: false
    };
  };
}

function translateSelectedCells(cells, dx, dy) {
  if (!dx && !dy) {
    return;
  }
  cells.forEach((cell) => {
    if (cell.isEdge?.()) {
      translateFreeEdge(cell, dx, dy);
    } else {
      cell.translate(dx, dy);
    }
  });
}

/**
 * 多选自由边时拖拽任一条选中边，整体平移所有选中图元
 */
export function initEdgeMultiSelectDrag(graph, { isEnabled = () => true } = {}) {
  disposeEdgeMultiSelectDrag();

  const originInteracting = graph.options.interacting;
  graph.options.interacting = wrapInteracting(graph, originInteracting);

  let dragging = false;
  let lastPoint = null;
  let dragTargets = null;
  let batched = false;

  const cleanup = () => {
    dragging = false;
    lastPoint = null;
    dragTargets = null;
    if (batched) {
      graph.stopBatch('edge-multi-drag');
      batched = false;
    }
    document.removeEventListener('mousemove', onPointerMove, true);
    document.removeEventListener('mouseup', onPointerUp, true);
    document.removeEventListener('pointermove', onPointerMove, true);
    document.removeEventListener('pointerup', onPointerUp, true);
    document.removeEventListener('pointercancel', onPointerUp, true);
    window.removeEventListener('blur', onPointerUp, true);
  };

  const onPointerMove = (e) => {
    if (!dragging || !lastPoint || !dragTargets?.length) {
      return;
    }
    if (e.buttons === 0) {
      cleanup();
      return;
    }
    const current = graph.clientToLocal(e.clientX, e.clientY);
    const dx = current.x - lastPoint.x;
    const dy = current.y - lastPoint.y;
    if (!dx && !dy) {
      return;
    }
    if (!batched) {
      graph.startBatch('edge-multi-drag');
      batched = true;
    }
    translateSelectedCells(dragTargets, dx, dy);
    lastPoint = current;
  };

  const onPointerUp = () => {
    if (!dragging) {
      return;
    }
    cleanup();
  };

  const bindDragListeners = () => {
    document.addEventListener('mousemove', onPointerMove, true);
    document.addEventListener('mouseup', onPointerUp, true);
    document.addEventListener('pointermove', onPointerMove, true);
    document.addEventListener('pointerup', onPointerUp, true);
    document.addEventListener('pointercancel', onPointerUp, true);
    window.addEventListener('blur', onPointerUp, true);
  };

  const onCellMouseDown = ({ e, cell }) => {
    if (!isEnabled() || isMultiSelectModifier(e) || isEdgeToolTarget(e)) {
      return;
    }
    if (!shouldGroupDragFromEdge(graph, cell)) {
      return;
    }

    e.preventDefault();
    e.stopPropagation();

    dragging = true;
    lastPoint = graph.clientToLocal(e.clientX, e.clientY);
    dragTargets = graph.getSelectedCells().filter(isMovableCell);
    bindDragListeners();
  };

  graph.on('cell:mousedown', onCellMouseDown);

  disposeFn = () => {
    graph.off('cell:mousedown', onCellMouseDown);
    graph.options.interacting = originInteracting;
    cleanup();
    disposeFn = null;
  };
}

export function disposeEdgeMultiSelectDrag() {
  if (disposeFn) {
    disposeFn();
  }
}
