export default class Style {
  execute(cellConfig, caseObj, result) {
    if (result === true) {
      this.toEffect(cellConfig, caseObj);
    } else {
      this.toOrg(cellConfig, caseObj);
    }
  }
  //变化到指定样式
  toEffect(cellConfig, caseObj) {
    if (caseObj.touchOff.style) {
      caseObj.touchOff.style.forEach((item) => {
        if (item.type == 'add' || item.type == 'change') {
          cellConfig.cell.attr(item.attrName, item.attrValue);
          // cellConfig.cell.attr(item.attrName, item.attrValue, { silent: true });
        } else if (item.type == 'remove') {
          cellConfig.cell.attr(item.attrName, '');
        }
      });
    }
    // cellConfig.cell.attr(caseObj.touchOff.style);
  }
  //恢复到最初样式
  toOrg(cellConfig, caseObj) {
    // cellConfig.cell.removeAttrByPath('water/visibility');
    // cellConfig.cell.removeAttrs({ silent: false });
    if (caseObj.touchOff.style) {
      caseObj.touchOff.style.forEach((item) => {
        if (item.type == 'add') {
          cellConfig.cell.attr(item.attrName, '');
          // cellConfig.cell.attr(item.attrName, item.attrValue);
        } else if (item.type == 'remove' || item.type == 'change') {
          cellConfig.cell.attr(item.attrName, item.orgAttrValue);
        }
      });
    }
    // cellConfig.cell.setAttrs(cellConfig.orgCell.attrs, { overwrite: true });
  }
}
