const HORIZONTAL_PRESETS = {
  left: { refX: '0%', refX2: 0, textAnchor: 'left', xAlign: 'left' },
  center: { refX: '50%', refX2: 0, textAnchor: 'middle', xAlign: 'middle' },
  right: { refX: '100%', refX2: 0, textAnchor: 'right', xAlign: 'right' }
};

const VERTICAL_PRESETS = {
  top: { refY: '0%', refY2: 0, yAlign: 'top', textVerticalAnchor: 'top' },
  middle: { refY: '50%', refY2: 0, yAlign: 'middle', textVerticalAnchor: 'middle' },
  bottom: { refY: '100%', refY2: 0, yAlign: 'bottom', textVerticalAnchor: 'bottom' }
};

function isNear(value, target, epsilon = 0.05) {
  if (value === undefined || value === null) {
    return false;
  }
  const str = String(value);
  if (str.endsWith('%')) {
    const pct = parseFloat(str) / 100;
    return Math.abs(pct - target) < epsilon;
  }
  const n = parseFloat(str);
  if (Number.isNaN(n)) {
    return false;
  }
  return Math.abs(n - target) < epsilon;
}

export function inferTextHorizontalAlign(attrs = {}) {
  const { refX, textAnchor, xAlign } = attrs;
  if (xAlign === 'middle' || textAnchor === 'middle' || isNear(refX, 0.5)) {
    return 'center';
  }
  if (xAlign === 'right' || textAnchor === 'right' || isNear(refX, 1)) {
    return 'right';
  }
  return 'left';
}

export function inferTextVerticalAlign(attrs = {}) {
  const { refY, yAlign, textVerticalAnchor } = attrs;
  const anchor = textVerticalAnchor || yAlign;
  if (anchor === 'middle' || isNear(refY, 0.5)) {
    return 'middle';
  }
  if (anchor === 'bottom' || isNear(refY, 1)) {
    return 'bottom';
  }
  return 'top';
}

export function getHorizontalAlignmentAttrs(horizontal) {
  return (
    HORIZONTAL_PRESETS[horizontal] ?? HORIZONTAL_PRESETS.left
  );
}

export function getVerticalAlignmentAttrs(vertical) {
  return VERTICAL_PRESETS[vertical] ?? VERTICAL_PRESETS.middle;
}
