import { Stencil } from '@antv/x6-plugin-stencil';
import { cloneDeep } from 'lodash';
import {
  SUPER_G_NAME,
  D3_G_NAME,
  DEFAULT_LABEL_SELECTOR,
  NODE_TYPES,
  NODE_TYPE_NAME
} from '../constants/Constants';
import { shapeList } from '../config/NodeList.js';
import { imageList } from '../config/ImageList.js';
import { nanoid } from 'nanoid';
import { initChartsNode } from '../config/ChartNodeList';
import { AUTO_SELECT_ON_ADDED_FLAG } from '../constants/Constants';
class StencilController {
  constructor() {
    this.stencils = [];
  }
  changeAllStencilGroup(graph, groups = []) {
    this.stencils.forEach((stencil) => {
      this.changeStencilGroup(graph, stencil, groups);
    });
    localStorage.setItem('select_groups', JSON.stringify(groups));
  }
  changeStencilGroup(graph, stencil, groups = []) {
    stencil.stopListening();
    this.groups = this.getSelectGroups();
    this.groups.forEach((groupName) => {
      try {
        stencil.removeGroup(groupName);
      } catch (error) {
        error;
      }
    });
    groups.forEach((groupName) => {
      let groupItems = imageList[groupName];
      stencil.addGroup({
        title: groupName,
        name: groupName,
        collapsed: true,
        graphHeight: this.calcGraphHeight(groupItems),
        layoutOptions: {
          rowHeight: 100
        }
      });
      let nodes = this.packageImgNode(graph, groupItems, groupName);
      stencil.load(nodes, groupName);
      /* let nodes = this.nodesObj[groupName];
      if (!nodes) {
        nodes = this.nodesObj[groupName] = this.packageImgNode(
          graph,
          imageList[groupName],
          groupName
        );
      }
      stencil.load(nodes, groupName); */
    });

    stencil.startListening();
  }
  async getStencils(
    graph,
    getDragNodeCellback = (node) => node,
    getDropNodeCellback = (node) => node
  ) {
    let nodesObj = this.nodesObj;
    if (!nodesObj) {
      nodesObj = {};
      for (let [key, value] of Object.entries(shapeList)) {
        nodesObj[key] = this.packageNode(graph, value, key);
      }
      this.nodesObj = nodesObj;
    }
    const customeNodes = await this.getCustomNodes();
    // #region 初始化 stencil
    let stencil = new Stencil({
      title: '全部展开/折叠',
      target: graph,
      stencilGraphWidth: 300,
      stencilGraphHeight: 0,
      //   stencilGraphHeight: 180,
      collapsable: true,
      search(cell, keyword) {
        return cell.store.data.label.indexOf(keyword) !== -1;
      },
      placeholder: '搜索',
      getDragNode: (sourceNode) => {
        let nodeType = sourceNode.prop(NODE_TYPE_NAME);
        if (nodeType === NODE_TYPES.echarts) {
          let resultNode = sourceNode.clone();
          resultNode.removeAttrByPath('foreignObject/style/transform');
          resultNode = getDragNodeCellback(resultNode);
          return resultNode;
        }
        let imageNode = imageList[sourceNode.store.data.groupKey];
        let shapeNodes = shapeList[sourceNode.store.data.groupKey];
        let searchShapeNode;
        if (imageNode) {
          let node = imageNode.find(
            (item) => item.key === sourceNode.store.data.key
          );
          searchShapeNode = this.packageImagNodeJson(node);
        } else if (shapeNodes) {
          // debugger;
          searchShapeNode = shapeList[sourceNode.store.data.groupKey].find(
            (item) => item.key === sourceNode.store.data.key
          );
        } else {
          let node = customeNodes.find(
            (item) => item.key === sourceNode.store.data.key
          );
          searchShapeNode = this.packageImagNodeJson(node);
        }
        //追加默认最顶级g标签
        let shapeNode = cloneDeep(searchShapeNode);
        shapeNode.options.markup = [
          {
            tagName: 'g',
            selector: D3_G_NAME,
            children: [
              {
                tagName: 'g',
                selector: SUPER_G_NAME,
                children: shapeNode.options.markup
              }
            ]
          }
        ];
        let node = graph.createNode({
          ...shapeNode.options,
          shape: shapeNode.shape,
          label: shapeNode.label,
          key: sourceNode.store.data.key,
          groupKey: sourceNode.store.data.groupKey
        });
        let size = node.store.data.size;
        let hw = size.height / size.width;
        let width = 100;
        let height = 100 * hw;
        node.size({ width, height }, { silent: true });
        node = getDragNodeCellback(node);
        return node;
      },
      getDropNode: (draggingNode) => {
        let resultNode = draggingNode.clone();
        resultNode = getDropNodeCellback(resultNode);

        // 标记：仅对“拖拽落到画布”的节点做自动选中（在 node:added 时处理）
        const data =
          resultNode.getData?.() ?? resultNode.store?.data?.data ?? {};
        if (resultNode.setData) {
          resultNode.setData({ ...data, [AUTO_SELECT_ON_ADDED_FLAG]: true });
        } else if (resultNode.store?.data) {
          resultNode.store.data.data = {
            ...(resultNode.store.data.data ?? {}),
            [AUTO_SELECT_ON_ADDED_FLAG]: true
          };
        }

        return resultNode;
      },
      validateNode: (droppingNode) => {
        const groupKey = droppingNode.store?.data?.groupKey;
        const key = droppingNode.store?.data?.key;
        if (!groupKey || key == null) return true;

        const shapeGroup = shapeList[groupKey];
        if (!shapeGroup) return true;

        const shapeConfig = shapeGroup.find((item) => item.key === key);
        if (!shapeConfig?.validateDrop) return true;

        const result = shapeConfig.validateDrop(droppingNode, graph, shapeConfig);
        return result !== false;
      },
      groups: [
        {
          title: '基础图元',
          name: 'basis',
          graphHeight: this.calcGraphHeight(nodesObj['basis']),
          collapsed: true,
          layoutOptions: {
            rowHeight: 100
          }
        },
        {
          title: '图表',
          name: 'charts',
          graphHeight: this.calcGraphHeight(nodesObj['charts']),
          collapsed: true,
          layoutOptions: {
            center: true,
            columns: 2,
            columnWidth: 140,
            rowHeight: 100,
            dy: 120,
            dx: 150,
            resizeToFit: false
          }
        },
        {
          title: '风扇',
          name: 'fan',
          collapsed: true,
          graphHeight: this.calcGraphHeight(nodesObj['fan']),
          layoutOptions: {
            rowHeight: 100
          }
        },
        {
          title: '生产',
          name: 'machine',
          graphHeight: this.calcGraphHeight(nodesObj['machine']),
          collapsed: true,
          layoutOptions: {
            rowHeight: 110
          }
        },
        {
          title: '自定义',
          name: 'custom',
          graphHeight: this.calcGraphHeight(customeNodes),
          collapsed: true,
          layoutOptions: {
            rowHeight: 110
          }
        }
      ],
      layoutOptions: {
        columns: 3,
        columnWidth: 80,
        rowHeight: 55,
        resizeToFit: true
      }
    });
    let nodes = this.packageImgNode(graph, customeNodes, 'custom');
    stencil.load(nodes, 'custom');
    for (let [key] of Object.entries(shapeList)) {
      stencil.load(nodesObj[key], key);
    }
    let chartsNodes = this.chartsNodes;
    if (!chartsNodes) {
      this.chartsNodes = chartsNodes = initChartsNode(graph);
    }
    if (chartsNodes) {
      stencil.load(chartsNodes, 'charts');
    }
    this.stencils.push(stencil);
    let selectGroups = this.getSelectGroups();
    this.changeStencilGroup(graph, stencil, selectGroups);
    return stencil;
  }
  async getCustomNodes() {
    try {
      const response = await fetch('/webtopo/custom/index.json');
      console.log(response);
      const fileList = await response.json();
      return fileList ?? [];
    } catch (error) {
      console.error('Error fetching file list:', error);
    }
  }
  calcGraphHeight(nodes) {
    return !nodes?.length ? 0 : Math.ceil(nodes.length / 3) * 130;
  }
  getSelectGroups() {
    let selectGroups = [];
    try {
      let saveGroups = localStorage.getItem('select_groups');
      if (saveGroups) {
        this.groups = selectGroups = JSON.parse(saveGroups);
      }
    } catch (error) {
      localStorage.removeItem('select_groups');
    }
    return selectGroups;
  }
  packageImagNodeJson({
    name,
    url = {},
    status,
    attrs,
    tagName = 'image',
    preserveAspectRatio = false
  }) {
    // item.name.length > 6?
    return {
      label: name,
      shape: 'super-node',
      options: {
        preserveAspectRatio: preserveAspectRatio,
        width: 400,
        height: 400,
        markup: [
          {
            tagName: 'rect',
            selector: 'selectorRect',
            attrs: {
              x: 0,
              y: 0,
              fill: 'none',
              pointerEvents: 'visible'
            }
          },
          {
            name: '图片',
            tagName: tagName,
            selector: 'body',
            attrs: {
              width: '204px',
              height: '204px'
            }
          }
        ],
        status,
        attrs: {
          selectorRect: {
            refWidth: 1,
            refHeight: 1
          },
          body: {
            preserveAspectRatio: 'none meet',
            refWidth: 1,
            refHeight: 1,
            xlinkHref: url,
            ...attrs
          }
        }
        // attrs
        /* attrs: {
          body: {
            preserveAspectRatio: 'none meet', //使图片可被拉伸，解除宽高比锁定
            refWidth: 1,
            refHeight: 1,
            href: url
          }
        } */
      }
    };
  }
  packageImgNode(graph, shapes, groupKey) {
    return shapes.map((item) => {
      let copyItem = this.packageImagNodeJson(item);
      copyItem.options.attrs = copyItem.options.attrs ?? {};
      copyItem.options.attrs[DEFAULT_LABEL_SELECTOR] = {
        text: copyItem.label,
        fill: '#888',
        fontSize: 12,
        fontWeight: 600,
        refX: '50%',
        refY: '120%',
        textAnchor: 'middle',
        textVerticalAnchor: 'top',
        fontFamily: 'Arial, helvetica, sans-serif',
        textWrap: {
          width: '100%',
          height: 20,
          ellipsis: true
        }
      };
      item.key = item.url;
      if (item.shape != 'custom-vue-node') {
        copyItem.options.markup = copyItem.options.markup ?? [];
        copyItem.options.markup.push({
          tagName: 'text',
          selector: DEFAULT_LABEL_SELECTOR
        });
        copyItem.options.markup.push({
          tagName: 'title',
          selector: 'title'
        });
        copyItem.options.attrs['title'] = {
          text: copyItem.label
        };
      }

      return graph.createNode({
        key: item.url,
        groupKey: groupKey,
        shape: copyItem.shape ?? 'super-node',
        label: copyItem.label,
        ...copyItem.options
      });
    });
  }
  packageNode(graph, shapes, groupKey) {
    return shapes.map((item) => {
      let copyItem = cloneDeep(item);

      copyItem.options.attrs = copyItem.options.attrs ?? {};
      copyItem.options.attrs[DEFAULT_LABEL_SELECTOR] = {
        text: copyItem.label,
        fill: '#888',
        fontSize: 12,
        fontWeight: 600,
        refX: '50%',
        refY: '120%',
        textAnchor: 'middle',
        textVerticalAnchor: 'top',
        fontFamily: 'Arial, helvetica, sans-serif'
      };
      const id = nanoid();
      item.key = id;
      if (item.shape != 'custom-vue-node') {
        copyItem.options.markup = copyItem.options.markup ?? [];
        copyItem.options.markup.push({
          tagName: 'text',
          selector: DEFAULT_LABEL_SELECTOR
        });
        copyItem.options.markup.push({
          tagName: 'title',
          selector: 'title'
        });
        copyItem.options.attrs['title'] = {
          text: copyItem.label
        };
      }

      return graph.createNode({
        key: id,
        groupKey: groupKey,
        shape: copyItem.shape ?? 'super-node',
        label: copyItem.label,
        ...copyItem.options
      });
    });
  }
  clear() {
    this.stencils = [];
  }
}
export default new StencilController();
