export class Theme {
  constructor() {
    if (!Theme.instance) {
      this.chartThemes = {};
      this.themeSelect = {};
      this.initThemes();
      Theme.instance = this;
    }
    return Theme.instance;
  }
  initThemes() {
    let r = require.context('./theme', false, /\.js$/);
    r.keys().forEach((key) => {
      let m = r(key).default;
      let fileName = key.replaceAll('./', '');
      this.chartThemes[fileName] = m;
      this.themeSelect[fileName] = m.name;
    });
  }
  getTheme(fileName) {
    if (!fileName) {
      return {};
    }
    return this.chartThemes[fileName];
  }
  getThemeSelect() {
    return this.themeSelect;
  }
}
